<script setup lang="ts">
import {computed,ref} from 'vue'
import {api,post} from '../api'
import {usePolling} from '../usePolling'
import {number,price,time} from '../format'
import {liquidation,paperDirection,positionGross} from '../paper'
import type {AccountPerformance as Performance} from '../accountPerformance'
import AccountPerformance from '../components/AccountPerformance.vue'
import type {PaperOverview} from '../paper'
import PageIntro from '../components/PageIntro.vue'
import StatCard from '../components/StatCard.vue'
import TodayExecution from '../components/TodayExecution.vue'
const data=ref<PaperOverview|null>(null),performance=ref<Performance|null>(null),busy=ref(false),actionError=ref(''),asOf=ref(new Date().toISOString())
async function load(signal?:AbortSignal){try{const [account,review]=await Promise.all([api<PaperOverview>('/api/paper',{signal}),api<Performance>('/api/paper/performance',{signal})]);data.value=account;performance.value=review}finally{asOf.value=new Date().toISOString()}}
const {error}=usePolling(load,5000),s=computed(()=>data.value?.state),r=computed(()=>s.value?.rules)
const positions=computed(()=>[...(s.value?.positions??[])].sort((a,b)=>Number(!!b.quant)-Number(!!a.quant)||a.bucket-b.bucket))
async function toggle(){if(!s.value||busy.value)return;busy.value=true;actionError.value='';try{await post(`/api/paper/${s.value.enabled?'pause':'resume'}`);await load()}catch(e){actionError.value=e instanceof Error?e.message:String(e)}finally{busy.value=false}}
</script>
<template><PageIntro eyebrow="QUANT WORKSPACE · VIRTUAL ACCOUNT" title="量化工作台" description="仅虚拟资金 · 风险约每5秒检查 · 先看持仓，再看执行。"><div v-if="s" class="workspace-actions"><span class="run-state">{{s.enabled?'模拟运行中':'新仓已暂停'}}</span><button v-if="s.quantControl" class="replay-action" :disabled="busy" @click="toggle">{{busy?'处理中…':s.enabled?'暂停新开仓':'恢复新开仓'}}</button><RouterLink v-else class="replay-action" to="/execution">准备当前模拟策略 →</RouterLink></div></PageIntro>
<p v-if="error||actionError" role="alert" class="radar-notice">{{actionError||error}}。已有数据保留原时间。</p>
<template v-if="data&&s&&r">
<p v-if="s.reviewThresholdReached" role="status" class="radar-notice">已达到20%亏损复盘线。按剩余权益降风险继续实验，不补本金。</p><p v-if="s.entryBlockReason" role="status" class="radar-notice">新开仓等待：{{s.entryBlockReason}}。已有仓位继续风险管理。</p>
<div class="stats"><StatCard label="账户净值 · USDT" :value="performance?.current.equity==null?'待补证':number(performance.current.equity,2)" :foot="`本金 ${r.initialCash} · 可用 ${number(s.cash,2)}`"/><StatCard label="今日日初观测收益 · USDT" :value="performance?.day.net==null?'未知':number(performance.day.net,4)" :foot="performance?.day.returnPercent==null?'缺有效日初或截至采样':`观测区间 ${number(performance.day.returnPercent,3)}%`"/><StatCard label="保证金 U / 持仓数" :value="`${number(data.marginUsed,2)} / ${s.positions.length}`" :foot="`最多 ${r.maximumPositions} 笔 · 每份保证金最多 ${r.marginPerTrade} U`"/><StatCard label="90日窗口已观测最大回撤" :value="performance?.drawdown.maximumPercent==null?'暂无可信样本':number(performance.drawdown.maximumPercent,3)+'%'" :foot="`可信采样 ${performance?.drawdown.validSamples??0} · 起点 ${time(performance?.drawdown.firstValidAt)}`"/></div>
<AccountPerformance v-if="performance" :value="performance" compact/>
<div class="section-heading"><h2>持仓与风险 <span>{{s.positions.length}} / {{r.maximumPositions}}</span></h2><RouterLink to="/journal?view=holdings">查看持仓过程 →</RouterLink></div>
<p class="mobile-table-hint">表格可左右滑动，查看止损、目标和保证金。</p><div class="market-panel table-scroll"><table class="positions-table"><thead><tr><th>合约 / 方向</th><th>数量 / 入场</th><th>标记价 / 毛浮盈亏</th><th>止损 / 当前状态</th><th>两级目标</th><th>保证金 / 强平估算</th></tr></thead><tbody><tr v-for="p in positions" :key="p.id"><td><b>{{p.symbol}}</b><small>{{paperDirection(p.direction)}} · {{p.quant?.plan.leverage??r.leverage}}倍</small><span class="version-tag" :class="{inherited:!p.quant}">{{p.quant?'当前规则':'沿用入场规则'}}</span></td><td>{{number(p.quantity,6)}}<small>{{price(p.entryPrice)}}</small></td><td>{{price(p.lastMark)}}<small :class="{'negative':(positionGross(p,asOf)??0)<0,'positive':(positionGross(p,asOf)??0)>0}">{{positionGross(p,asOf)==null?'报价待更新':number(positionGross(p,asOf),4)+' U'}}</small></td><td>{{price(p.stopPrice)}}<small>{{p.quant?.pendingExit?'已触发退出，等待后续盘口':'等待触发，持续检查'}}</small></td><td>{{price(p.takePrice)}} / {{price(p.target2)}}<small>{{p.quant?.skipFirst?'首批低于网格未减':p.firstTaken?'首批已减':'首批待触发'}} · {{p.quant?.skipSecond?'次批低于网格未减':p.secondTaken?'尾仓跟踪中':'次批待触发'}}</small></td><td>{{number(p.remainingMargin,3)}} U<small>强平估算 {{price(liquidation(p,r))}}</small></td></tr><tr v-if="!positions.length"><td colspan="6" class="empty">目前没有模拟持仓。等待符合规则的新信号。</td></tr></tbody></table></div>
<p class="workspace-caption">账本更新 {{time(s.updatedAt)}}。毛浮盈亏未扣未来退出费；强平价含模型假设。沿用入场规则的仓位继续管理，与当前新仓共用现金和持仓额度。</p>
<TodayExecution/>
<details class="detail workspace-rules"><summary>账户规则与运行边界</summary><p>1,000 USDT分10份，每份保证金最多100，同时最多5笔；实际数量由风险与结构止损决定。暂停仅阻止新仓，持仓退出继续。20%亏损只作复盘提醒，按剩余权益降风险，不补本金。</p><p>各持仓按入场规则管理；新仓核对盘口、数量网格及实际资金费；最近10分钟资金费暂记。手续费、残余滑点及强平档位仍包含模型假设。断网、休眠或失鲜时不伪造成交，亏损可能超过计划。</p><p>当前执行 {{s.quantControl?.version??r.version}}，生效 {{time(s.quantControl?.activatedAt??s.executionStartedAt)}}。当前合计计划风险 {{number(data.openPlannedRisk,3)}} U；下一次小时分析 {{time(data.nextAnalysisAt)}}。</p><div class="context-actions"><RouterLink to="/execution">完整执行规则与费用 →</RouterLink><RouterLink to="/network">采集与流量 →</RouterLink></div></details>
</template><p v-else-if="!error" class="empty">正在读取账户与持仓。</p></template>
<style scoped>.paper-banner{display:flex;justify-content:space-between;align-items:center;gap:16px;padding:16px 20px;border:1px solid #325448;background:#122720;border-radius:8px;margin-bottom:22px;flex-wrap:wrap}.paper-banner span{font-size:12px;color:#9eb4ac}.positions-table small{display:block;overflow-wrap:anywhere}.version-tag{display:inline-block;padding:3px 7px;border:1px solid #305548;color:#89cbb3;font-size:10px;border-radius:4px;margin-top:8px}.version-tag.inherited{border-color:#4b4d50;color:#a8b3c1}.workspace-caption{font-size:11px;line-height:1.8;color:#8b9caa}.workspace-rules summary{font-size:13px}.stats{margin-top:12px}.positions-table td{padding-top:18px;padding-bottom:18px}.positions-table th{text-align:right}.positions-table th:first-child{text-align:left}.workspace-actions{display:flex;align-items:center;gap:16px}.run-state{color:#8bd0b3;font-size:12px}.page-title{margin-bottom:20px}.page-title :deep(h1){font-size:26px;margin:8px 0}.stats{margin-bottom:24px}.stats :deep(.stat){padding:15px 18px}.stats :deep(.stat strong){font-size:23px;margin:10px 0}.positions-table{font-size:12px}.positions-table td{padding-top:11px;padding-bottom:11px}.positions-table small{font-size:10px}.version-tag{margin-top:5px}@media(max-width:650px){.workspace-actions{width:100%;justify-content:space-between}.page-title :deep(h1){font-size:24px}}.mobile-table-hint{display:none}@media(max-width:850px){.mobile-table-hint{display:block;font-size:11px;color:#8da3af;margin:0 0 12px}.stats :deep(.stat strong){font-size:20px}}</style>
